/**
 * Chat Types
 * Persistent data shapes for AI conversations.
 * Lives in core so storage/ can reference them without importing from ai/.
 */

import type { NodeId } from './main-types';

/** Unique identifier for a chat message */
export type MessageId = string;

/** Origin of a chat message */
export type MessageSource = 'ai' | 'note' | 'tutorial';

/** MIME types accepted for note image attachments */
export type NoteImageMimeType = 'image/png' | 'image/jpeg' | 'image/webp';

/** Where an image attachment came from: uploaded from disk, retrieved from an image source, or generated by an image model */
export type AttachmentOrigin = 'note' | 'retrieved' | 'generated';

/** Source/license credit for a retrieved image */
export interface ImageAttribution {
  author?: string;
  license?: string;
  licenseUrl?: string;
  sourceName: string;
  sourcePageUrl?: string;
  attributionRequired?: boolean;
}

/**
 * Image attached to a chat message.
 * Note images are user-uploaded and stored inline as a base64 data URL.
 * Retrieved images carry a `sourceUrl` and optionally stored `dataUrl` bytes.
 * Generated images are stored bytes with no link, like uploads, and record
 * the prompt and model that produced them.
 * Local-only: attachments are never included in AI requests.
 */
export interface ChatImageAttachment {
  id: string;
  type: 'image';
  origin: AttachmentOrigin;
  mimeType: NoteImageMimeType;
  name: string;
  width: number;
  height: number;
  /** Downscaled bytes when stored locally; absent in link-only mode */
  dataUrl?: string;
  /** Remote source URL (retrieved images) */
  sourceUrl?: string;
  /** Full-resolution original URL for the lightbox (retrieved images) */
  fullUrl?: string;
  /** Credit metadata (retrieved images) */
  attribution?: ImageAttribution;
  /** The text sent to the image model, style suffix included (generated images) */
  prompt?: string;
  /** The image model id that drew it (generated images) */
  model?: string;
}

/** Individual message in a conversation */
export interface ChatMessage {
  id: MessageId;
  role: 'user' | 'assistant';
  content: string;
  timestamp: Date;
  source?: MessageSource;
  /**
   * The id this message was known by in the Markdown document it came from.
   * Written when a document creates the note, so re-running that document
   * replaces the note instead of adding a second copy.
   */
  externalId?: string;
  /** Image attachments (note uploads or retrieved images) */
  attachments?: ChatImageAttachment[];
}

/** Full conversation associated with a node */
export interface Conversation {
  nodeId: NodeId;
  messages: ChatMessage[];
  createdAt: Date;
  updatedAt: Date;
}
